import { LayoutDashboard, BarChart2, Shield, History, Settings, HelpCircle, LogOut } from 'lucide-react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const SidebarLink = ({ to, icon: Icon, label }: { to: string, icon: any, label: string }) => (
  <NavLink 
    to={to} 
    className={({ isActive }) => `
      flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-all
      ${isActive ? 'bg-blue-50 text-blue-600' : 'text-neutral-500 hover:bg-neutral-50 hover:text-neutral-900'}
    `}
  >
    <Icon className="w-5 h-5" />
    {label}
  </NavLink>
);

export default function Sidebar() {
  const navigate = useNavigate();
  const { logout, user } = useAuth();

  const handleLogout = async () => {
    try {
      await logout();
      navigate('/signin');
    } catch (error) {
      console.error('Logout failed:', error);
    }
  };

  return (
    <aside className="w-64 border-r border-neutral-100 flex flex-col h-screen sticky top-0 bg-white">
      <div className="p-6">
        <div className="flex items-center gap-3 mb-8">
          <div className="w-10 h-10 bg-black rounded-full flex items-center justify-center">
            <Shield className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="font-display font-bold text-sm leading-tight text-neutral-900 border-b border-transparent">Guardian Console</h1>
            <p className="text-[10px] text-neutral-500 uppercase tracking-wider font-semibold">Enterprise Tier</p>
          </div>
        </div>

        <nav className="space-y-1">
          <SidebarLink to="/dashboard" icon={LayoutDashboard} label="Dashboard" />
          <SidebarLink to="/analytics" icon={BarChart2} label="Analytics" />
          <SidebarLink to="/advisor" icon={Shield} label="Shields" />
          <SidebarLink to="/history" icon={History} label="History" />
          <SidebarLink to="/settings" icon={Settings} label="Settings" />
        </nav>
      </div>

      <div className="mt-auto p-6 space-y-6">
        <div className="bg-neutral-50 rounded-xl p-4 border border-neutral-100">
          <button className="w-full py-2 bg-white border border-neutral-200 rounded-lg text-xs font-semibold hover:bg-neutral-50 transition-colors">
            Upgrade Plan
          </button>
        </div>

        {user?.username && (
          <div className="bg-blue-50 rounded-lg p-3 border border-blue-100">
            <p className="text-xs font-semibold text-blue-900">Logged in as</p>
            <p className="text-xs text-blue-700 truncate">{user.username}</p>
            {user.isAdmin && (
              <p className="text-xs text-blue-600 font-semibold mt-1">Admin User</p>
            )}
          </div>
        )}

        <div className="space-y-1">
          <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-neutral-500 hover:text-neutral-900 transition-colors">
            <HelpCircle className="w-5 h-5" />
            Help Center
          </button>
          <button 
            onClick={handleLogout}
            className="w-full flex items-center gap-3 px-4 py-2 text-sm text-red-600 hover:text-red-700 hover:bg-red-50 rounded-lg transition-colors"
          >
            <LogOut className="w-5 h-5" />
            Sign Out
          </button>
        </div>
      </div>
    </aside>
  );
}

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import * as authApi from '../api/client';

export interface AuthContextType {
  user: authApi.AuthUserDto | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  isAdmin: boolean;
  login: (email: string, password: string) => Promise<void>;
  register: (username: string, email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  refreshUser: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

interface AuthProviderProps {
  children: ReactNode;
}

export const AuthProvider = ({ children }: AuthProviderProps) => {
  const [user, setUser] = useState<authApi.AuthUserDto | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Initialize auth state on component mount
  useEffect(() => {
    const initializeAuth = async () => {
      try {
        const currentUser = await authApi.getCurrentUser();
        setUser(currentUser);
      } catch (error) {
        console.error('Failed to initialize auth:', error);
        setUser(null);
      } finally {
        setIsLoading(false);
      }
    };

    initializeAuth();
  }, []);

  const login = async (email: string, password: string) => {
    try {
      setIsLoading(true);
      const loggedInUser = await authApi.login({ email, password });
      setUser(loggedInUser);
    } finally {
      setIsLoading(false);
    }
  };

  const register = async (username: string, email: string, password: string) => {
    try {
      setIsLoading(true);
      await authApi.register({ username, email, password });
      // Auto-login after registration
      const loggedInUser = await authApi.login({ email, password });
      setUser(loggedInUser);
    } finally {
      setIsLoading(false);
    }
  };

  const logout = async () => {
    try {
      setIsLoading(true);
      await authApi.logout();
      setUser(null);
    } finally {
      setIsLoading(false);
    }
  };

  const refreshUser = async () => {
    try {
      const currentUser = await authApi.getCurrentUser();
      setUser(currentUser);
    } catch (error) {
      console.error('Failed to refresh user:', error);
    }
  };

  const value: AuthContextType = {
    user,
    isLoading,
    isAuthenticated: user?.authenticated || false,
    isAdmin: user?.isAdmin || false,
    login,
    register,
    logout,
    refreshUser,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

import { ReactNode } from 'react';
import { Navigate } from 'react-router-dom';
import { useAuth } from './AuthContext';
import PageLoader from '../components/PageLoader';

interface ProtectedRouteProps {
  children: ReactNode;
  adminOnly?: boolean;
}

export const ProtectedRoute = ({ children, adminOnly = false }: ProtectedRouteProps) => {
  const { isAuthenticated, isAdmin, isLoading } = useAuth();

  if (isLoading) {
    return <PageLoader />;
  }

  if (!isAuthenticated) {
    return <Navigate to="/signin" replace />;
  }

  if (adminOnly && !isAdmin) {
    return <Navigate to="/dashboard" replace />;
  }

  return <>{children}</>;
};

import { Download, Plus, LogOut } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useState, useEffect } from 'react';
import Sidebar from '../components/Sidebar';
import { ResponsiveContainer, LineChart, Line, XAxis, YAxis, Tooltip, Area, AreaChart } from 'recharts';
import { useAuth } from '../context/AuthContext';
import { detectAiContent } from '../api/client';

const data = [
  { name: 'Intro', value: 5, historical: 10 },
  { name: 'Body 1', value: 45, historical: 35 },
  { name: 'Body 2', value: 65, historical: 55 },
  { name: 'Conclusion', value: 85, historical: 70 },
];

const CircularProgress = ({ percentage }: { percentage: number }) => {
  const radius = 70;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  return (
    <div className="relative flex flex-col items-center justify-center">
      <svg className="w-48 h-48 -rotate-90">
        <circle
          cx="96"
          cy="96"
          r={radius}
          stroke="currentColor"
          strokeWidth="12"
          fill="transparent"
          className="text-neutral-100"
        />
        <circle
          cx="96"
          cy="96"
          r={radius}
          stroke="currentColor"
          strokeWidth="12"
          fill="transparent"
          strokeDasharray={circumference}
          style={{ strokeDashoffset }}
          strokeLinecap="round"
          className="text-neutral-900 transition-all duration-1000 ease-out"
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center pt-2">
        <span className="text-5xl font-display font-bold tracking-tighter">{percentage}%</span>
        <span className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest mt-1">Likely AI Generated</span>
      </div>
    </div>
  );
};

export default function Dashboard() {
  const navigate = useNavigate();
  const { logout, user } = useAuth();
  const [aiPercentage, setAiPercentage] = useState(78);
  const [documentName, setDocumentName] = useState('Q3_Strategic_Initiative_v2.docx');
  const [isLoading, setIsLoading] = useState(false);

  const handleLogout = async () => {
    try {
      await logout();
      navigate('/signin');
    } catch (error) {
      console.error('Logout failed:', error);
    }
  };

  const handleNewScan = async () => {
    // Example: You could open a file upload modal or demo page
    const sampleText = `The strategic initiative outlined herein aims to consolidate our market position by leveraging synergistic operational frameworks. While historical data indicates a plateau in our primary demographic, predictive models suggest an untapped reservoir of engagement in secondary markets. We plan to execute a phased rollout over the next three quarters. Furthermore, establishing a cross-functional task force will facilitate the seamless integration of these new paradigms into our existing infrastructure.`;

    setIsLoading(true);
    try {
      const result = await detectAiContent(sampleText);
      // Update based on API response
      if (result && typeof result.aiProbability === 'number') {
        setAiPercentage(Math.round(result.aiProbability));
        setDocumentName('Sample_Analysis.docx');
      }
    } catch (error) {
      console.error('Detection failed:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex bg-white min-h-screen">
      <Sidebar />

      <main className="flex-1 p-12 max-w-6xl mx-auto">
        <header className="flex items-center justify-between mb-12">
          <div>
            <h1 className="font-display text-5xl font-bold tracking-tight mb-2">Document Analysis</h1>
            <p className="text-neutral-500 font-medium">Reviewing "{documentName}"</p>
            {user?.username && (
              <p className="text-xs text-neutral-400 mt-1">Logged in as: {user.username}</p>
            )}
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={handleNewScan}
              disabled={isLoading}
              className="flex items-center gap-2 px-4 py-2 border border-neutral-200 rounded-lg text-sm font-medium hover:bg-neutral-50 transition-colors disabled:opacity-50"
            >
              <Download className="w-4 h-4" />
              Export Report
            </button>
            <button 
              onClick={handleNewScan}
              disabled={isLoading}
              className="flex items-center gap-2 px-4 py-2 bg-black text-white rounded-lg text-sm font-medium hover:bg-neutral-800 transition-colors disabled:opacity-50"
            >
              <Plus className="w-4 h-4" />
              {isLoading ? 'Scanning...' : 'New Scan'}
            </button>
            <button
              onClick={handleLogout}
              className="flex items-center gap-2 px-4 py-2 border border-neutral-200 rounded-lg text-sm font-medium text-red-600 hover:bg-red-50 transition-colors"
            >
              <LogOut className="w-4 h-4" />
              Logout
            </button>
          </div>
        </header>

        <section className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-8">
          {/* AI Probability Card */}
          <div className="lg:col-span-1 bg-white border border-neutral-100 rounded-3xl p-8 flex flex-col items-center justify-center min-h-[360px] shadow-sm">
            <div className="self-start mb-auto text-[10px] font-bold text-neutral-400 uppercase tracking-widest flex items-center gap-1.5">
              <div className="w-1.5 h-1.5 rounded-full bg-neutral-900" />
              AI Probability
            </div>
            <CircularProgress percentage={aiPercentage} />
            <div className="mt-auto" />
          </div>

          {/* Confidence Trends Card */}
          <div className="lg:col-span-2 bg-white border border-neutral-100 rounded-3xl p-8 flex flex-col shadow-sm">
            <div className="flex items-center justify-between mb-8">
              <div className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest">Confidence Trends</div>
              <div className="flex p-1 bg-neutral-50 rounded-lg border border-neutral-100">
                <button className="px-3 py-1 bg-white shadow-sm rounded-md text-[10px] font-bold uppercase tracking-wider">This Scan</button>
                <button className="px-3 py-1 text-neutral-400 text-[10px] font-bold uppercase tracking-wider">Historical</button>
              </div>
            </div>

            <div className="flex-1 -mx-8 -mb-4 h-48">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={data}>
                  <defs>
                    <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#171717" stopOpacity={0.1}/>
                      <stop offset="95%" stopColor="#171717" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <XAxis 
                    dataKey="name" 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{ fontSize: 10, fill: '#A3A3A3', fontWeight: 500 }}
                    dy={16}
                  />
                  <YAxis hide domain={[0, 100]} />
                  <Tooltip 
                    contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontSize: '12px' }}
                  />
                  <Area 
                    type="monotone" 
                    dataKey="value" 
                    stroke="#171717" 
                    strokeWidth={2} 
                    fillOpacity={1} 
                    fill="url(#colorValue)" 
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
        </section>

        {/* Sentence Level Analysis */}
        <section className="bg-white border border-neutral-100 rounded-3xl p-8 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-2 text-[10px] font-bold text-neutral-400 uppercase tracking-widest">
              <span className="w-4 h-4 border border-neutral-200 rounded flex items-center justify-center text-[10px]">≡</span>
              Sentence-level Analysis
            </div>
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-1.5 text-[10px] font-medium text-neutral-500">
                <div className="w-2 h-2 rounded-full bg-neutral-900" />
                High Probability
              </div>
              <div className="flex items-center gap-1.5 text-[10px] font-medium text-neutral-500">
                <div className="w-2 h-2 rounded-full bg-blue-100" />
                Human Written
              </div>
            </div>
          </div>

          <div className="space-y-6 text-neutral-700 leading-loose">
            <p>
              The strategic initiative outlined herein aims to consolidate our market position by leveraging synergistic operational frameworks. 
              <span className="bg-blue-50 border-b border-neutral-900 mx-1 px-1 py-0.5 rounded cursor-help transition-colors hover:bg-blue-100">
                While historical data indicates a plateau in our primary demographic, predictive models suggest an untapped reservoir of engagement in secondary markets.
              </span>
              We plan to execute a phased rollout over the next three quarters.
              <span className="bg-blue-50 border-b border-neutral-900 mx-1 px-1 py-0.5 rounded cursor-help transition-colors hover:bg-blue-100">
                Furthermore, establishing a cross-functional task force will facilitate the seamless integration of these new paradigms into our existing infrastructure, ensuring minimal disruption to current workflows.
              </span>
              Initial focus will be on the APAC region, followed by EMEA.
            </p>
          </div>
        </section>
      </main>

      <footer className="fixed bottom-0 right-0 left-64 bg-white/80 backdrop-blur pb-6 pt-4 px-12 border-t border-neutral-50">
        <div className="max-w-6xl mx-auto flex items-center justify-between text-[10px] text-neutral-400 font-medium">
          <div className="uppercase tracking-widest flex items-center gap-2">
            © 2024 AI GUARDIAN INC. <span className="text-neutral-200">|</span> BUILT FOR PRECISION.
          </div>
          <div className="flex items-center gap-6 uppercase tracking-widest">
            <a href="#" className="hover:text-neutral-900">Privacy Policy</a>
            <a href="#" className="hover:text-neutral-900">Terms of Service</a>
            <a href="#" className="hover:text-neutral-900">API Documentation</a>
            <a href="#" className="hover:text-neutral-900">Status</a>
          </div>
        </div>
      </footer>
    </div>
  );
}

import { motion } from 'motion/react';
import { Link, useNavigate } from 'react-router-dom';
import { Shield, ArrowRight } from 'lucide-react';
import { useState } from 'react';
import { useAuth } from '../context/AuthContext';

export default function SignUp() {
  const navigate = useNavigate();
  const { register } = useAuth();
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Validate form
    if (!formData.name.trim()) {
      setError('Full name is required');
      return;
    }
    if (!formData.email.trim()) {
      setError('Email is required');
      return;
    }
    if (!formData.password || formData.password.length < 8) {
      setError('Password must be at least 8 characters');
      return;
    }

    // Password strength validation
    if (!/[A-Z]/.test(formData.password) || !/[a-z]/.test(formData.password) || !/[0-9]/.test(formData.password)) {
      setError('Password must contain uppercase, lowercase, and numbers');
      return;
    }

    setIsLoading(true);

    try {
      await register(formData.name, formData.email, formData.password);
      navigate('/dashboard');
    } catch (err: any) {
      const errorMessage = err?.response?.data?.message || err?.message || 'Registration failed. Please try again.';
      setError(errorMessage);
      console.error('Registration error:', err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#FAFAFA] flex flex-col justify-center py-12 sm:px-6 lg:px-8">
      <div className="sm:mx-auto sm:w-full sm:max-w-md">
        <div className="flex justify-center">
          <Link to="/" className="w-12 h-12 bg-neutral-900 rounded-xl flex items-center justify-center shadow-lg shadow-neutral-200 hover:scale-105 transition-transform">
            <Shield className="w-6 h-6 text-white" />
          </Link>
        </div>
        <h2 className="mt-6 text-center font-display text-3xl font-bold tracking-tight text-neutral-900">
          Create an account
        </h2>
        <p className="mt-2 text-center text-sm text-neutral-500 font-medium">
          Already have an account?{' '}
          <Link to="/signin" className="text-neutral-900 hover:text-neutral-700 underline underline-offset-4 font-semibold">
            Sign in instead
          </Link>
        </p>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md">
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white py-10 px-4 shadow-2xl shadow-neutral-200/50 sm:rounded-3xl sm:px-10 border border-neutral-100"
        >
          {error && (
            <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg text-sm text-red-700">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label htmlFor="name" className="block text-sm font-semibold text-neutral-900">
                Full name
              </label>
              <div className="mt-2">
                <input
                  id="name"
                  name="name"
                  type="text"
                  autoComplete="name"
                  required
                  value={formData.name}
                  onChange={handleChange}
                  className="block w-full rounded-lg border-0 py-3 text-neutral-900 shadow-sm ring-1 ring-inset ring-neutral-200 placeholder:text-neutral-400 focus:ring-2 focus:ring-inset focus:ring-neutral-900 sm:text-sm sm:leading-6 px-4 font-medium transition-all"
                  placeholder="Jane Doe"
                />
              </div>
            </div>

            <div>
              <label htmlFor="email" className="block text-sm font-semibold text-neutral-900">
                Work email address
              </label>
              <div className="mt-2">
                <input
                  id="email"
                  name="email"
                  type="email"
                  autoComplete="email"
                  required
                  value={formData.email}
                  onChange={handleChange}
                  className="block w-full rounded-lg border-0 py-3 text-neutral-900 shadow-sm ring-1 ring-inset ring-neutral-200 placeholder:text-neutral-400 focus:ring-2 focus:ring-inset focus:ring-neutral-900 sm:text-sm sm:leading-6 px-4 font-medium transition-all"
                  placeholder="name@company.com"
                />
              </div>
            </div>

            <div>
              <label htmlFor="password" className="block text-sm font-semibold text-neutral-900">
                Password
              </label>
              <p className="mt-1 text-xs text-neutral-500">
                Min 8 characters with uppercase, lowercase, and numbers
              </p>
              <div className="mt-2">
                <input
                  id="password"
                  name="password"
                  type="password"
                  autoComplete="new-password"
                  required
                  value={formData.password}
                  onChange={handleChange}
                  className="block w-full rounded-lg border-0 py-3 text-neutral-900 shadow-sm ring-1 ring-inset ring-neutral-200 placeholder:text-neutral-400 focus:ring-2 focus:ring-inset focus:ring-neutral-900 sm:text-sm sm:leading-6 px-4 font-medium transition-all"
                  placeholder="••••••••"
                />
              </div>
            </div>

            <div>
              <button
                type="submit"
                disabled={isLoading}
                className="flex w-full justify-center items-center gap-2 rounded-full bg-neutral-900 px-3 py-3.5 text-sm font-semibold text-white shadow-xl hover:bg-neutral-800 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-900 transition-all hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isLoading ? 'Creating account...' : 'Get started'}
                {!isLoading && <ArrowRight className="w-4 h-4" />}
              </button>
            </div>
          </form>

          <div className="mt-8">
            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-neutral-200" />
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="bg-white px-4 text-neutral-500 font-medium">Or continue with</span>
              </div>
            </div>

            <div className="mt-6 grid grid-cols-2 gap-4">
              <button
                type="button"
                className="flex w-full items-center justify-center gap-3 rounded-xl bg-white px-3 py-3 text-sm font-semibold text-neutral-900 shadow-sm ring-1 ring-inset ring-neutral-200 hover:bg-neutral-50 transition-all focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-zinc-900"
              >
                <svg className="h-5 w-5" viewBox="0 0 24 24" aria-hidden="true">
                  <path
                    d="M12.0003 4.75C13.7703 4.75 15.3553 5.36002 16.6053 6.54998L20.0303 3.125C17.9502 1.19 15.2353 0 12.0003 0C7.31028 0 3.25527 2.69 1.28027 6.60998L5.27028 9.70498C6.21525 6.86002 8.87028 4.75 12.0003 4.75Z"
                    fill="#EA4335"
                  />
                  <path
                    d="M23.49 12.275C23.49 11.49 23.415 10.73 23.3 10H12V14.51H18.47C18.18 15.99 17.34 17.25 16.08 18.1L19.945 21.1C22.2 19.01 23.49 15.92 23.49 12.275Z"
                    fill="#4285F4"
                  />
                  <path
                    d="M5.26498 14.2949C5.02498 13.5699 4.88501 12.7999 4.88501 11.9999C4.88501 11.1999 5.01998 10.4299 5.26498 9.7049L1.275 6.60986C0.46 8.22986 0 10.0599 0 11.9999C0 13.9399 0.46 15.7699 1.28 17.3899L5.26498 14.2949Z"
                    fill="#FBBC05"
                  />
                  <path
